  // S53: medicine catalogue search, pack prefill, the add check, side-effect notes, the supporter notice and the authenticity prompt.
  "medicines.search.label": "Medicine name",
  "medicines.search.hint": "Start typing a brand or generic name. You can also type any name that is not listed.",
