  "medicines.search.unverified": "Our list entry has not been checked against NAFDAC's register yet.",
  "medicines.pack.read_button": "Fill this in from a photo of the pack",
  "medicines.pack.prefilled": "We filled this in from your photo. Please check every box against your pack before you add it.",
  "medicines.pack.low_confidence": "The photo was hard to read, so please check every detail carefully.",
  "medicines.pack.confirm": "I have checked these details against my pack.",
  "medicines.pack.unreadable": "We could not read that photo. You can type the details yourself.",
  "medicines.rxphoto.note": "A photo of your prescription is kept for your reference only. It does not add a medicine to your list.",
  "medicines.addcheck.title": "Before you add this medicine",
  "medicines.addcheck.advice.high": "These two medicines can affect each other in a way your care team should look at. Please message your care team before you take them together. Do not stop a medicine your care team prescribed unless they tell you to.",
  "medicines.addcheck.advice.review": "These two medicines can affect each other. It is worth checking with your care team. Keep taking your medicines as prescribed until you hear from them.",
  "medicines.addcheck.advice.note": "A small note to share with your care team: these two medicines can have a minor effect on each other.",
  "medicines.addcheck.advice.duplicate": "You may already take a medicine of this kind. Two of the same kind can add side effects without adding benefit. Please check with your care team before you take both. Do not stop a prescribed medicine on your own.",
  "medicines.addcheck.limits": "This check looks at the most common problems only. No warning does not mean two medicines are safe together. Your care team or pharmacist can check the full picture.",
  "medicines.addcheck.not_checked": "We could not run the interaction check just now. You can still add this, and your care team or pharmacist can check it for you.",
  "medicines.addcheck.contact": "Message your care team",
  "medicines.addcheck.continue": "Add it anyway",
  "medicines.sideeffect.title": "Side effects to share",
  "medicines.sideeffect.hint": "Write down anything you notice after taking this medicine. Your care team sees it at your next visit.",
  "medicines.sideeffect.add": "Add a note",
  "medicines.sideeffect.saved": "Saved. Your care team will see this at your next visit.",
  "medicines.sideeffect.urgent": "If you feel very unwell, do not wait for a visit. Use the emergency steps in the app.",
  "medicines.supporter.notice.title": "A check-in with no record",
  "medicines.supporter.notice.body": "Someone you support has a care plan check with no record yet. You may want to call them.",
  "medicines.mas.add_prompt": "If your pack has a scratch panel, you can check the code with NAFDAC's free text service (send the code to 38353) before you start. Not every pack has a panel.",
  "medicines.mas.collect_prompt": "When you collect your medicine, check the pack for a scratch panel. If there is one, send the code to 38353 for a free reply from NAFDAC. A reply is NAFDAC's, not ours.",
  // S08y: the same ingredient under two names, governed interaction rules (warn only), the NAFDAC number note and how to check it,
  // the supporter's "today's doses" view, and the low-supply link to the pharmacy page. Nothing here says a pack is genuine or a medicine is safe.
  "medicines.addcheck.advice.same_ingredient": "This looks like it has the same active ingredient as a medicine already on your list, sometimes under a different brand name. Taking both can mean more of it than you intend. Please check with your care team or pharmacist before you take both. Do not stop a prescribed medicine on your own.",
  "medicines.rules.advice.high": "Your care team has flagged this pair of ingredients for a closer look. Please message your care team before you take them together. Do not stop a medicine your care team prescribed unless they tell you to.",
  "medicines.rules.advice.review": "Your care team has flagged this pair of ingredients to check. It is worth asking them. Keep taking your medicines as prescribed until you hear from them.",
  "medicines.rules.advice.note": "A small note to share with your care team about this pair of ingredients.",
  "medicines.nafdac.field_label": "NAFDAC number on the pack (optional)",
  "medicines.nafdac.field_hint": "It is printed on the box, for example A4-1234 or 04-1234. We keep it as a note for you and your care team. We do not check it for you.",
  "medicines.nafdac.invalid": "That did not look like a NAFDAC number, so we did not save it. They look like A4-1234 or 04-1234. Your medicine was added. You can add the number later.",
  "medicines.nafdac.saved": "NAFDAC number saved as a note.",
  "medicines.nafdac.save_failed": "We could not save the NAFDAC number just now. Your medicine was added.",
  "medicines.nafdac.shown": "NAFDAC number you noted: {number}",
  "medicines.nafdac.verify.title": "How to check this number with NAFDAC",
  "medicines.nafdac.verify.not_a_check": "Saving a number here is only a note. It does not tell you whether a pack is genuine. NAFDAC can.",
  "medicines.nafdac.verify.step_greenbook": "Search the number in NAFDAC's Greenbook at greenbook.nafdac.gov.ng. You can search by product name or registration number and see its status.",
  "medicines.nafdac.verify.step_scratch": "If your pack has a scratch panel, follow the instructions printed with it for NAFDAC's text service. Not every pack has one.",
  "medicines.nafdac.verify.step_helpline": "For questions, you can call NAFDAC on 0700-1-623322. If anything looks wrong, do not take the medicine and message your care team.",
