  // S61/S62: condition pathway messages. DRAFT clinical wording: the Chief Medical Officer signs it like the EMG and TRI codes. In-app guidance only (INV-07).
  "pathway.dm_red.title": "Get help now",
  "pathway.dm_red.body": "Your blood sugar is dangerously low, or you have signs of a severe low. If you are awake and can swallow, take 15 g of fast sugar now (about 3 teaspoons of sugar in water), then go to the nearest hospital now. If you cannot swallow or are not fully awake, give nothing by mouth and get someone to take you to hospital now. Your care team has been alerted.",
  "pathway.dm_dka.title": "Go to hospital now",
  "pathway.dm_dka.body": "Your blood sugar is very high and ketones are raised. Go to the nearest hospital now. Do not stop any insulin you take. Your care team has been alerted.",
  "pathway.dm_low.title": "Treat a low blood sugar",
  "pathway.dm_low.body": "Your reading is low. Take 15 g of fast sugar now (about 3 teaspoons of sugar in water), then check again in 15 minutes. If you feel confused, cannot swallow or are not fully awake, get help now. Your care team will follow up.",
  "pathway.dm_review.title": "Your care team will review this",
  "pathway.dm_review.body": "Your reading has been passed to your care team to review. Keep logging your readings. If you feel unwell, go to the nearest hospital.",
  "pathway.as_red.title": "Get help now",
  "pathway.as_red.body": "Your breathing needs urgent help. Use your reliever as directed, and go to the nearest hospital now if you cannot finish a sentence or the reliever is not helping. Your care team has been alerted.",
  "pathway.gen_review.title": "Your care team will review this",
  "pathway.gen_review.body": "Your care team will look at your latest results. Keep logging as usual. If you feel unwell, go to the nearest hospital.",
