  // S23: AI scribe consent, recording, and draft review.
  "scribe.consent.title": "AI note-taking",
  "scribe.consent.body": "Your care team would like to use an AI tool to help write notes about this consultation. Your clinician types or pastes notes of the conversation into the tool, which creates a draft summary. Your clinician reviews and edits it before it becomes part of your record. The text is not kept by the tool. You can say no, and your care will not be affected.",
  "scribe.consent.agree": "I agree",
  "scribe.consent.clinician_body": "The patient decides in the app, when they join the room. If they have allowed the AI note-taker for this consultation you can start it. If not, write the note yourself.",
  "scribe.consent.start": "Start AI note-taker",
  "scribe.consent.write_myself": "Write the note myself",
  "scribe.consent.not_allowed": "The patient has not allowed the AI note-taker for this consultation in the app. Write the note yourself.",
  "scribe.consent.not_used_label": "AI note-taker not used",
  "scribe.consent.start_failed": "We could not start the AI note-taker. You can write the note yourself.",
  "scribe.consent.decline": "No, thank you",
  "scribe.consent.declined_label": "Patient declined",
  "scribe.consent.revoked_label": "Patient withdrew consent",
  "scribe.input.heading": "Draft the note with AI",
  "scribe.input.label": "Consultation notes",
  "scribe.input.help": "Paste or type what was said and found in this consultation. Start lines with Doctor: or Patient: so the AI can tell who said what. The text is sent to the AI to draft the note and is not stored.",
  "scribe.input.placeholder": "Patient: I have had headaches for two weeks, mostly in the evening.\nDoctor: Any chest pain or blurred vision?\nPatient: No chest pain. Sometimes my vision blurs.\nDoctor: BP today 164/98. Review in two weeks.",
  "scribe.input.generate": "Draft the note",
  "scribe.input.too_short": "Add a little more text to draft from.",
  "scribe.language.label": "Patient summary language",
  "scribe.language.en": "English",
