  "symptom.blocked.under18.title": "This checker is for adults",
  "symptom.blocked.under18.body": "We cannot check symptoms for anyone under 18 yet. Please message your care team in the app and tell them what is worrying you. If the child is very unwell, cannot drink, is very sleepy, has a fit or is struggling to breathe, go to the nearest hospital now.",
  "symptom.blocked.dob.title": "We need a date of birth first",
  "symptom.blocked.dob.body": "The checker needs a date of birth so it can be safe for the person it is for. Please add it to the profile, then come back. If this is an emergency, go to the nearest hospital now.",
  "symptom.blocked.dob.cta": "Add a date of birth",
  "symptom.proxy_pregnancy.note": "You told us this person may be pregnant. Pregnancy changes how urgent this is, so we have treated it as needing prompt attention. Questions about pregnancy can only be answered by the person themselves, so we have not asked more or saved that answer.",
  "symptom.blocked.pregnancy_self_only.title": "Questions about pregnancy are for the person themselves",
  "symptom.blocked.pregnancy_self_only.body": "If this is an emergency, go to the nearest hospital now. Heavy bleeding, a fit, severe pain in the belly, struggling to breathe, or a very bad headache with changes in sight should not wait. Questions about pregnancy can only be answered by the person themselves, so we cannot ask them here for someone else. Please ask them to open the check on their own account.",
  "symptom.blocked.message_cta": "Message your care team",
  "symptom.blocked.concern_label": "Tell us what is worrying you (optional). It goes on a booking you make for yourself, as a note for the doctor.",
