  "programme.sponsor_sees_title": "What your sponsor sees and never sees",
  "programme.sponsor_sees_body": "Your sponsor sees counts of how many people are enrolled and how many have joined, how many are taking part, and overall averages for groups of at least {minimum} people. They never see your name, your readings, your results, your mental health, women's health or pregnancy information, or anything about you personally.",
  "programme.who_pays_title": "Who pays",
  "programme.who_pays_body": "If your employer or sponsor pays for part of your care, those items show under your plan as covered by them, and you are not charged for them. Joining does not charge you anything. Anything else you choose to buy is paid by you, or by a supporter you ask.",
  // Joining with an employer's organisation code puts the person on that employer's staff list (public.employer_join_with_code stores the name, phone and email as 'claimed'). Say so plainly.
  "employer.join.sees_title": "What your employer sees",
  "employer.join.sees_body": "Your employer's staff list shows your name, your phone number and your email, and that you joined. About your health, your employer sees group totals only. Your employer does not see your readings, your results, your medicines or your messages.",
