  "tour.overview.body": "This is Overview. It shows what to do today, such as a reading to log or a medicine to take. Tap an item to do it, and it is ticked off when you finish.",
  "tour.vitals.body": "This is Vitals and symptoms. Log a blood pressure or blood sugar reading, or note how you feel. It takes a few seconds and it saves on your phone even without internet, then sends when you are back online.",
