  "exchange.download_title": "Download your record",
  "exchange.download_body": "A file in the FHIR standard with your readings, results, medicines, conditions, allergies, vaccinations and a list of your documents. It leaves out reproductive health, mental health and your private notes. Items inside the other sections are not sorted by what they are for, so read it before you hand it on.",
