  "exchange.ips.title": "Download my summary (IPS)",
  "exchange.ips.body": "A short summary in the International Patient Summary layout, a format many health systems around the world use. It lists your problems, allergies, medicines, vaccinations, released lab results and readings, in sections, so a clinic that reads this format can find each part.",
  "exchange.ips.leaves_out": "It has no separate reproductive health or mental health section, and it leaves out your private notes and your documents. Items inside the other sections are not sorted by what they are for, so read it before you hand it on. Lab results appear only once your care team has released them. Only your most recent readings and results are included. A reading from a wearable is marked as an estimate. A section with nothing recorded says so; that does not mean there is nothing to record.",
  "exchange.ips.not_validated": "This file follows the IPS layout but has not been checked against an official test tool, and it is not approved for any national system. It was made from your own record and has not been checked or signed by a clinician.",
  "exchange.ips.button": "Download my summary (IPS)",
  "exchange.ips.preview_link": "See what is inside first",
  "exchange.ips.preview_title": "What is inside your summary",
  "exchange.ips.preview_intro": "This shows what the summary says now. The file is made again when you download it, so it may differ if your record has changed. Showing the summary is listed under \"Who made a copy of your record\", the same as a download, so it only happens when you ask. Printing this page also works as a paper copy.",
  "exchange.ips.preview_show": "Show me what is inside",
  "exchange.ips.preview_failed": "Your summary could not be shown just now. Please try again in a little while.",
  "exchange.ips.preview_empty": "Nothing is recorded yet, so there is nothing to put in a summary.",
  "exchange.ips.section_empty": "Nothing is recorded here.",
  "exchange.ips.left_out_title": "What is left out",
  "exchange.ips.left_out_body": "There is no separate reproductive health or mental health section, and private notes and documents are never part of this summary. Items inside the other sections are not sorted by what they are for, so read the lines above before you hand it on. Lab results appear only once released to you.",
