  "signupinv.title": "Sign-up invites",
  "signupinv.intro": "Sign-up is open to everyone until you switch on invite-only sign-up. When it is on, a new person needs an invite for their phone number or email, an invite code, a number someone has paid for, or an account you create for them. People who already have an account are never affected.",
