  "community.join.title": "Before you join",
  "community.join.handle_explainer": "You will be given a made-up name for this group. Nobody in the group sees your real name, phone number or email.",
  "community.join.rules_ack": "I have read the group rules and agree to follow them",
  "community.join.consent_title": "Your safety and your privacy",
  "community.join.consent": "What the groups are. Tarragon community groups are for adults, 18 and over, to share day-to-day experience with others who live with a similar health condition. They are not medical advice, and they are not a way to reach your care team in an emergency. If you think you are in danger, go to your nearest hospital now.\n\nYour made-up name. In each group you get a made-up name. The people in the group never see your real name, phone number or email, and your membership is not shown anywhere else on Tarragon.\n\nWhat we keep. We keep what you post, your made-up name for the group, and a record of the checks our team makes on posts. Posts you remove or delete are wiped from our records after 90 days. We never share your posts or your membership with employers, insurers or sponsors.\n\nWho can read what. A small team of trained moderators reads posts that our automatic checks hold back, and every picture before anyone else sees it. They see your made-up name only, never who you are.\n\nThe one exception. If something you write suggests you may be in danger, a safety reviewer may read it, and a Tarragon doctor, the Chief Medical Officer or an administrator may look up who you are, so that someone can check that you are safe. Each lookup is written down with a reason, and the Chief Medical Officer is told every time. This is the only time your name is linked to what you wrote.\n\nYour choices. You can leave a group at any time and choose to delete your posts when you do. You can hide one person's posts. You can appeal a decision about your post. You can ask us to erase your account, and your posts are then no longer linked to you.\n\nKeeping everyone safe. Please do not share phone numbers, email addresses, links or social media names. Posts that do are stopped.",
