  "medicines.report.none": "No scheduled medicines in this period.",
  "medicines.report.footnote_self_report": "This is a record of what the patient marked in the app. It is not a grade, and it is not a measure of how well a treatment is working. A skipped dose counts as not taken and is shown on its own. Medicines taken only when needed are left out. The record follows the medicines you take now: a medicine you have stopped or had changed is not included for earlier weeks.",
