  "partnerops.title": "Partner webhooks",
  "partnerops.intro": "The endpoints partners receive events on, and which bus events go to them. Events carry ids only. Every change here is written to the audit log. Signing keys are shown once, when you create them, and cannot be read again.",
  "partnerops.search.hint": "Partner webhook endpoints: status, last success and failure, rotate a signing key, switch an auto-disabled endpoint back on, and the event map.",
  "partnerops.load_failed": "This could not be read, so nothing here can be taken as healthy. Reload to try again.",
  "partnerops.banner.unreadable": "The event bus status could not be read, so it is not known whether the event processor (process-events) is running. Do not add a mapping until it is.",
  "partnerops.banner.never": "No event has ever been completed by the event processor (process-events). It may not be deployed. Until it is, a new mapping sends nothing, and its deliveries go to the dead letter as \"no handler registered\".",
  "partnerops.banner.stalled": "The event processor (process-events) looks stalled: a subscriber has deliveries waiting with no recent success. Check that it is deployed and its secrets are set before relying on a mapping.",
  "partnerops.banner.partner_stuck": "The event processor works for other subscribers, but nothing has ever been delivered to the partner webhook subscribers, and they have deliveries waiting or dead. The partner.webhook handler is probably not deployed (process-events needs redeploying). Do not add or rely on a mapping until it is.",
  "partnerops.error.rotate_unknown": "The answer did not come back, so the key may or may not have been rotated. Reload and check the key version in the table. If it went up, the old key still works until its grace window ends; then rotate again.",
  "partnerops.result.rotated": "Signing key rotated. Copy the new key now.",
  "partnerops.result.reenabled": "Endpoint switched back on.",
  "partnerops.result.mapping_saved": "Mapping saved.",
